combo_sqls.focused_short:
SELECT CAST(SUM(IIF(T2.Consumption > 528.3, 1, 0)) AS FLOAT) * 100.0 / COUNT(DISTINCT T2.CustomerID)
FROM yearmonth AS T2
WHERE T2.Date = '201202';

